-- Dungeon Master's Guide v3.5 Chapter 7: rods, pp. 233-237.
-- Includes the complete standard rod catalog, all 18 metamagic-rod variants,
-- rod construction/activation rules, Table 7-19, and the Rod of Wonder effect table.
-- Mechanical text is summarized; the supplied DMG and appended errata remain authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dmg-3.5','dungeon-masters-guide-3-5','Dungeon Master''s Guide','DMG','Wizards of the Coast','dnd','3.5',
        'Core Rulebook II; source for D&D v3.5 magic items, treasure, special materials, and Dungeon Master rules.',NULL,1,0,NULL);

-- Metamagic rods: lesser affects spells of 3rd level or lower, normal 6th or lower,
-- greater 9th or lower. Each may be used three times per day.
WITH desired(id,slug,name,feat,tier,max_spell_level,price_copper) AS (VALUES
 ('dmg-rod-enlarge-lesser','rod-metamagic-enlarge-lesser','Metamagic Rod, Enlarge, Lesser','Enlarge Spell','lesser',3,300000),
 ('dmg-rod-enlarge','rod-metamagic-enlarge','Metamagic Rod, Enlarge','Enlarge Spell','normal',6,1100000),
 ('dmg-rod-enlarge-greater','rod-metamagic-enlarge-greater','Metamagic Rod, Enlarge, Greater','Enlarge Spell','greater',9,2450000),
 ('dmg-rod-extend-lesser','rod-metamagic-extend-lesser','Metamagic Rod, Extend, Lesser','Extend Spell','lesser',3,300000),
 ('dmg-rod-extend','rod-metamagic-extend','Metamagic Rod, Extend','Extend Spell','normal',6,1100000),
 ('dmg-rod-extend-greater','rod-metamagic-extend-greater','Metamagic Rod, Extend, Greater','Extend Spell','greater',9,2450000),
 ('dmg-rod-silent-lesser','rod-metamagic-silent-lesser','Metamagic Rod, Silent, Lesser','Silent Spell','lesser',3,300000),
 ('dmg-rod-silent','rod-metamagic-silent','Metamagic Rod, Silent','Silent Spell','normal',6,1100000),
 ('dmg-rod-silent-greater','rod-metamagic-silent-greater','Metamagic Rod, Silent, Greater','Silent Spell','greater',9,2450000),
 ('dmg-rod-empower-lesser','rod-metamagic-empower-lesser','Metamagic Rod, Empower, Lesser','Empower Spell','lesser',3,900000),
 ('dmg-rod-empower','rod-metamagic-empower','Metamagic Rod, Empower','Empower Spell','normal',6,3250000),
 ('dmg-rod-empower-greater','rod-metamagic-empower-greater','Metamagic Rod, Empower, Greater','Empower Spell','greater',9,7300000),
 ('dmg-rod-maximize-lesser','rod-metamagic-maximize-lesser','Metamagic Rod, Maximize, Lesser','Maximize Spell','lesser',3,1400000),
 ('dmg-rod-maximize','rod-metamagic-maximize','Metamagic Rod, Maximize','Maximize Spell','normal',6,5400000),
 ('dmg-rod-maximize-greater','rod-metamagic-maximize-greater','Metamagic Rod, Maximize, Greater','Maximize Spell','greater',9,12150000),
 ('dmg-rod-quicken-lesser','rod-metamagic-quicken-lesser','Metamagic Rod, Quicken, Lesser','Quicken Spell','lesser',3,3500000),
 ('dmg-rod-quicken','rod-metamagic-quicken','Metamagic Rod, Quicken','Quicken Spell','normal',6,7550000),
 ('dmg-rod-quicken-greater','rod-metamagic-quicken-greater','Metamagic Rod, Quicken, Greater','Quicken Spell','greater',9,17000000)
)
INSERT INTO dnd35_items
 (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
  category,price_copper,weight_pounds,size,hardness,hit_points)
SELECT d.id,'dmg-3.5','236',d.slug,d.name,
       'A metamagic rod that applies '||d.feat||' to qualifying spells without changing their spell level or casting time beyond the feat''s own effect.',
       'Usable three times per day. '||CASE d.tier WHEN 'lesser' THEN 'Affects spells of 3rd level or lower.' WHEN 'normal' THEN 'Affects spells of 6th level or lower.' ELSE 'Affects spells of 9th level or lower.' END||' Only one metamagic rod can modify a given spell, but the caster may combine a rod with metamagic feats they possess.',
       0,NULL,1,'magic',d.price_copper,NULL,NULL,10,10
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_items i WHERE i.source_id='dmg-3.5' AND i.slug=d.slug AND i.owner_user_id IS NULL);

WITH desired(item_id) AS (VALUES
 ('dmg-rod-enlarge-lesser'),('dmg-rod-enlarge'),('dmg-rod-enlarge-greater'),
 ('dmg-rod-extend-lesser'),('dmg-rod-extend'),('dmg-rod-extend-greater'),
 ('dmg-rod-silent-lesser'),('dmg-rod-silent'),('dmg-rod-silent-greater'),
 ('dmg-rod-empower-lesser'),('dmg-rod-empower'),('dmg-rod-empower-greater'),
 ('dmg-rod-maximize-lesser'),('dmg-rod-maximize'),('dmg-rod-maximize-greater'),
 ('dmg-rod-quicken-lesser'),('dmg-rod-quicken'),('dmg-rod-quicken-greater')
)
INSERT OR IGNORE INTO dnd35_magic_items
 (item_id,aura_school_id,caster_level,manifester_level,aura_strength,activation,activation_text,slot,
  maximum_charges,recharge_text,enhancement_bonus,craft_cost_copper,craft_xp_cost,crafting_text,crafting_prerequisites)
SELECT d.item_id,NULL,17,NULL,'strong','use_activated','Apply the rod while casting a qualifying spell; the rod itself does not grant the metamagic feat.','main_hand',3,'Three uses per day.',0,NULL,NULL,'Craft Rod; appropriate metamagic feat.',NULL
FROM desired d;

-- Standard nonepic rods.
WITH desired(id,page,slug,name,description,rules_text,price_copper,weight_pounds,caster_level,aura_strength,activation,activation_text,maximum_charges,recharge_text,enhancement_bonus,craft_cost_copper,craft_xp_cost,crafting_text) AS (VALUES
('dmg-rod-immovable','234-235','rod-immovable','Immovable Rod','A flat iron rod with one button that can anchor itself in place.','Pressing the button is a move action. The rod remains fixed in place even against gravity and supports up to 8,000 pounds. A DC 30 Strength check can move it up to 10 feet in one round.',500000,5.0,10,'moderate','other','Press the button as a move action to fix or release the rod.',NULL,NULL,0,NULL,NULL,'Craft Rod; levitate.'),
('dmg-rod-metal-mineral-detection','235','rod-metal-mineral-detection','Rod of Metal and Mineral Detection','A rod that points toward a specified metal or mineral.','While concentrating for a full round, the wielder learns the direction and approximate quantity of the specified metal or mineral within 30 feet, detecting the largest concentration first.',1050000,NULL,9,'moderate','other','Specify a metal or mineral and concentrate for a full round.',NULL,NULL,0,NULL,NULL,'Craft Rod; locate object.'),
('dmg-rod-cancellation','234','rod-cancellation','Rod of Cancellation','A potent one-use rod that drains the magic from another item.','Touch a magic item; it makes a DC 23 Will save or permanently loses all magical properties. If held, use the holder''s Will save if better and resolve a melee touch attack. The rod becomes brittle and useless after successfully draining one item. A wish or miracle can restore the drained item.',1100000,5.0,17,'strong','use_activated','Touch the target magic item; a held target requires a melee touch attack.',1,'Successfully cancelling an item consumes the rod permanently.',0,NULL,NULL,'Craft Rod; Mordenkainen''s disjunction.'),
('dmg-rod-wonder','236-237','rod-wonder','Rod of Wonder','A chaotic rod that produces a random magical effect every time it is activated.','Activating the rod is a standard action. Roll on the Rod of Wonder effect table each time. The listed effects are typical and the DM may alter them for a campaign.',1200000,NULL,10,'moderate','other','Standard action; roll d% on the Rod of Wonder effect table.',NULL,NULL,0,NULL,NULL,'Craft Rod; confusion; creator must be chaotic.'),
('dmg-rod-python','235-236','rod-python','Rod of the Python','A four-foot rod that acts as a +1/+1 quarterstaff and transforms into a giant constrictor snake for a good possessor.','Throwing the rod to the ground is a standard action; by the end of the round it becomes a giant constrictor snake that obeys the owner and retains the +1 attack/damage enhancement. It returns to rod form as a full-round action on command or if it moves more than 100 feet away. If slain in snake form, it cannot transform again for 3 days. It functions only for a good possessor.',1300000,10.0,10,'moderate','other','Throw to the ground as a standard action to transform; returning to rod form is a full-round action.',NULL,'If the snake form is slain, transformation is unavailable for 3 days.',1,NULL,NULL,'Craft Rod; Craft Magic Arms and Armor; baleful polymorph; creator must be good.'),
('dmg-rod-flame-extinguishing','235','rod-flame-extinguishing','Rod of Flame Extinguishing','A rod that suppresses fires and can damage fiery creatures.','Touching a Medium or smaller nonmagical fire extinguishes it without spending a charge. Large nonmagical fires and Medium or smaller magical fires cost 1 charge; continual magical flames are suppressed for 6 rounds. The wielder can ready the rod to counter instantaneous fire spells. Large or larger magical fires cost 2 charges. Spending 3 charges on a melee touch against a fire creature deals 6d6 damage.',1500000,NULL,12,'strong','use_activated','Touch or ready the rod as appropriate to the fire effect being suppressed.',10,'The rod replenishes its 10 charges each day.',0,NULL,NULL,'Craft Rod; pyrotechnics.'),
('dmg-rod-viper','236','rod-viper','Rod of the Viper','An evil +2 heavy mace whose head can become a venomous serpent.','Functions as a +2 heavy mace. Once per day on command for 10 minutes, successful strikes also deliver poison: 1d10 Constitution damage immediately and 1d10 Constitution damage 1 minute later, each negated by Fortitude DC 14. The rod functions only for an evil possessor.',1900000,NULL,10,'moderate','command_word','Command once per day; the serpent-head form lasts 10 minutes.',NULL,'One activation per day.',2,NULL,NULL,'Craft Rod; Craft Magic Arms and Armor; poison; creator must be evil.'),
('dmg-rod-enemy-detection','234','rod-enemy-detection','Rod of Enemy Detection','A rod that locates creatures hostile to the wielder even when hidden, invisible, disguised, or ethereal.','When activated it pulses and points toward the nearest hostile creature within 60 feet. Full-round concentration reveals the direction of the nearest enemy and the total number of hostile creatures in range. Each use can last up to 10 minutes.',2350000,NULL,10,'moderate','other','Activate as a standard action; full-round concentration gives precise nearest-enemy direction and hostile count.',3,'Three uses per day; each use lasts up to 10 minutes.',0,NULL,NULL,'Craft Rod; true seeing.'),
('dmg-rod-splendor','236','rod-splendor','Rod of Splendor','A lavish rod that enhances Charisma and creates magnificent clothing and a grand pavilion.','While held or carried, grants +4 enhancement Charisma. Once per day it creates fine clothing, furs, and jewels that last 12 hours and vanish if sold, given away, used as components, forcibly taken, or removed by the possessor. Once per week it creates a 60-foot pavilion with furnishings, food, and service for up to 100 people for 1 day.',2500000,NULL,12,'strong','other','Charisma bonus is continuous while held/carried; clothing once per day; pavilion once per week.',NULL,'Clothing once per day; pavilion once per week.',0,NULL,NULL,'Craft Rod; fabricate; Mordenkainen''s magnificent mansion.'),
('dmg-rod-withering','236','rod-withering','Rod of Withering','A +1 light mace that attacks ability scores instead of hit points.','Functions as a +1 light mace but deals no hit point damage. A successful melee touch deals 1d4 Strength damage and 1d4 Constitution damage; Fortitude DC 17 negates. On a critical hit, the ability damage becomes permanent ability drain.',2500000,NULL,13,'strong','use_activated','Make a melee touch attack.',NULL,NULL,1,NULL,NULL,'Craft Rod; Craft Magic Arms and Armor; contagion.'),
('dmg-rod-thunder-lightning','236','rod-thunder-lightning','Rod of Thunder and Lightning','A +2 light mace with thunder and lightning powers.','Functions as a +2 light mace. Thunder once per day can make the next hit count as +3 and force Fortitude DC 16 or stun. Lightning once per day adds electricity damage. Thunderclap once per day is a shout-like 2d6 sonic blast (Fortitude DC 16 partial, deafened 2d6 rounds). Lightning Stroke once per day fires a 200-foot 9d6 bolt (Reflex DC 16 half). Once per week both can be combined; the bolt treats damage dice of 1 or 2 as 3 and a single DC 16 Reflex save applies.',3300000,NULL,9,'moderate','other','Individual powers use their described free-action or standard-action activations.',NULL,'Thunder, lightning, thunderclap, and lightning stroke each once per day; combined thunder-and-lightning once per week.',2,NULL,NULL,'Craft Rod; Craft Magic Arms and Armor; lightning bolt; shout.'),
('dmg-rod-negation','235','rod-negation','Rod of Negation','A rod that suppresses the magical functions of magic items.','Points a pale ray at one magic item as a ranged touch attack. The ray functions as greater dispel magic at caster level 15 but only against magic items. Instantaneous item effects require a readied action. The item receives no saving throw. Artifacts cannot be negated.',3700000,NULL,15,'strong','use_activated','Point at a magic item and make a ranged touch attack; ready an action to negate instantaneous effects.',3,'Three uses per day.',0,NULL,NULL,'Craft Rod; dispel magic; limited wish or miracle.'),
('dmg-rod-absorption','234','rod-absorption','Rod of Absorption','A rod that absorbs hostile spell energy and lets the wielder spend that energy to cast prepared or known spells.','While held, it automatically absorbs single-target spells and rays directed at the wielder or the wielder''s gear, requiring no action. It can absorb at most 50 spell levels over its lifetime. Absorbed levels become stored energy; the wielder may spend stored levels to cast prepared spells without expending preparation, subject to normal material components, or otherwise use the stored energy as described by the source. Once 50 spell levels have ever been absorbed, the rod cannot absorb more.',5000000,NULL,15,'strong','other','Automatic absorption requires no action while the rod is in hand; stored energy is spent when casting.',NULL,'Lifetime absorption capacity is 50 spell levels and does not recharge.',0,NULL,NULL,'Craft Rod; spell turning.'),
('dmg-rod-flailing','234-235','rod-flailing','Rod of Flailing','A rod that transforms into a +3 dire flail and can briefly ward its wielder.','On command it becomes a +3 dire flail. The wielder may fight with both heads, taking -2 on all attacks as though using Two-Weapon Fighting. Once per day as a free action it grants +4 deflection AC and +4 resistance on saving throws for 10 minutes. Transforming between rod and weapon form is a move action.',5000000,NULL,9,'moderate','other','Transform as a move action; the defensive ward is a free action once per day.',NULL,'Defensive ward once per day.',3,NULL,NULL,'Craft Rod; Craft Magic Arms and Armor; bless.'),
('dmg-rod-rulership','236','rod-rulership','Rod of Rulership','A royal scepter able to compel the obedience of a vast number of creatures.','Activating it is a standard action and can command creatures within 120 feet totaling up to 300 Hit Dice. Creatures with Intelligence 12 or higher may make Will DC 16 to resist. Ruled creatures obey as absolute subjects, but a command contrary to their nature breaks the magic. The rod functions for 500 total minutes, not necessarily continuous, then crumbles to dust.',6000000,NULL,20,'strong','other','Standard action to begin rulership over creatures within 120 feet.',NULL,'Provides 500 total minutes of rulership over its lifetime; duration need not be continuous.',0,2750000,2200,'Craft Rod; mass charm monster.'),
('dmg-rod-security','236','rod-security','Rod of Security','A rod that transports a group into a safe nondimensional paradise.','A standard action transports the possessor and as many as 199 other connected/touching creatures into a pocket paradise. Unwilling creatures get Will DC 17. Maximum stay is 200 days divided by the number of creatures, rounded down; more than 200 creatures cannot be affected. Creatures do not age there, natural healing is doubled, food and fresh water are abundant, and climate is comfortable. On expiration, dismissal, or dispelling, travelers return to their original locations with displacement as needed if occupied. The rod can be activated once per week.',6100000,NULL,20,'strong','other','Standard action; transports the wielder and creatures touching the rod or connected through physical contact.',NULL,'One activation per week.',0,NULL,NULL,'Craft Rod; gate.'),
('dmg-rod-lordly-might','235','rod-lordly-might','Rod of Lordly Might','A ten-pound rod with six buttons that combines several weapon forms, spell-like powers, climbing utility, and a battering ram.','Normally functions as a +2 light mace. Its six buttons change the rod or invoke powers. Button 1 can form a +1 flaming longsword; button 2 a +4 battleaxe; button 3 a +3 shortspear or longspear with adjustable total length from 6 to 15 feet. Its once-per-day powers include hold person by touch (Will DC 14), a fear effect against nearby viewers (Will DC 16 partial), and a life-draining touch that deals 2d4 damage and heals the wielder by the same amount (Will DC 17 half). Additional buttons provide the source-described ladder/climbing and battering-ram functions.',7000000,10.0,19,'strong','other','Press the appropriate button to select a form or invoke a power; spell-like powers are each once per day.',NULL,'Each spell-like power is usable once per day.',2,NULL,NULL,'Craft Rod; Craft Magic Arms and Armor; bull''s strength; fear; hold person; inflict light wounds; creator must have Strength 12.'),
('dmg-rod-alertness','234','rod-alertness','Rod of Alertness','A +1 light mace that enhances vigilance and provides detection, defensive, and animation powers.','Functions as a +1 light mace and grants +1 insight on initiative while held. While grasped, the wielder can use standard actions for detect evil, detect good, detect chaos, detect law, detect magic, discern lies, light, and see invisibility. Once per day, planting the rod and activating it alerts the wielder to harmful creatures within 120 feet, places a prayer-like benefit on allies within 20 feet, and maintains mental alertness for 10 minutes. Once per day it can animate up to eleven Small objects around the rod for 11 rounds.',8500000,NULL,11,'moderate','other','Detection powers are standard actions; planted alert/prayer effect and animated-object power are each once per day.',NULL,'Alert/prayer effect once per day; animate objects once per day; detection powers at will while grasped.',1,NULL,NULL,'Craft Rod; alarm; detect chaos; detect evil; detect good; detect law; detect magic; discern lies; light; see invisibility; prayer; animate objects.' )
)
