-- Shared rod construction/physical rules and metamagic behavior.
WITH desired(slug,name,page,kind,summary,tags,mechanics) AS (VALUES
('dmg-rod-physical-statistics','Rod Physical Statistics','233','rule',
 'Rods are generally scepterlike; many are sturdy enough to function as clubs or light maces. Standard sturdy rods have AC 9, 10 hit points, hardness 10, and break DC 27.',
 '["magic-items","rods","objects"]','{"armorClass":9,"hitPoints":10,"hardness":10,"breakDc":27}'),
('dmg-rod-special-qualities','Random Rod Special Qualities','233','table',
 'For a randomly generated rod, 01 is intelligent, 02-31 bears a clue to its function, and 32-100 has no special quality. Rods with charges can never be intelligent.',
 '["magic-items","rods","intelligent-items","random-generation"]','{"ranges":[[1,1,"intelligent"],[2,31,"function-clue"],[32,100,"none"]],"chargedRodsCannotBeIntelligent":true}'),
('dmg-metamagic-rod-operation','Metamagic Rod Operation','236','rule',
 'Metamagic rods let a spellcaster apply the named metamagic feat to spells three times per day without altering the spell slot used. The rod does not grant the feat; only one metamagic rod can modify one spell, but the caster may also apply their own metamagic feats.',
 '["magic-items","rods","metamagic"]','{"usesPerDay":3,"oneMetamagicRodPerSpell":true,"canCombineWithCastersOwnMetamagic":true,"rodDoesNotGrantFeat":true,"lesserMaxSpellLevel":3,"normalMaxSpellLevel":6,"greaterMaxSpellLevel":9}'),
('dmg-table-7-19-rods','Table 7-19: Rods','233-234','table',
 'Random-generation table for medium and major rods.',
 '["magic-items","rods","random-generation","table-7-19"]',
 '{"medium":[[1,7,"rod-metamagic-enlarge-lesser"],[8,14,"rod-metamagic-extend-lesser"],[15,21,"rod-metamagic-silent-lesser"],[22,28,"rod-immovable"],[29,35,"rod-metamagic-empower-lesser"],[36,42,"rod-metal-mineral-detection"],[43,53,"rod-cancellation"],[54,57,"rod-metamagic-enlarge"],[58,61,"rod-metamagic-extend"],[62,65,"rod-metamagic-silent"],[66,71,"rod-wonder"],[72,79,"rod-python"],[80,83,"rod-metamagic-maximize-lesser"],[84,89,"rod-flame-extinguishing"],[90,97,"rod-viper"],[98,99,"rod-metamagic-empower"],[100,100,"rod-metamagic-quicken-lesser"]],"major":[[1,4,"rod-cancellation"],[5,6,"rod-metamagic-enlarge"],[7,8,"rod-metamagic-extend"],[9,10,"rod-metamagic-silent"],[11,14,"rod-wonder"],[15,18,"rod-python"],[19,21,"rod-flame-extinguishing"],[22,25,"rod-viper"],[26,30,"rod-enemy-detection"],[31,36,"rod-metamagic-enlarge-greater"],[37,42,"rod-metamagic-extend-greater"],[43,48,"rod-metamagic-silent-greater"],[49,53,"rod-splendor"],[54,58,"rod-withering"],[59,64,"rod-metamagic-empower"],[65,69,"rod-thunder-lightning"],[70,73,"rod-metamagic-quicken-lesser"],[74,77,"rod-negation"],[78,80,"rod-absorption"],[81,84,"rod-flailing"],[85,86,"rod-metamagic-maximize"],[87,88,"rod-rulership"],[89,90,"rod-security"],[91,92,"rod-lordly-might"],[93,94,"rod-metamagic-empower-greater"],[95,96,"rod-metamagic-quicken"],[97,98,"rod-alertness"],[99,99,"rod-metamagic-maximize-greater"],[100,100,"rod-metamagic-quicken-greater"]]}'),
('dmg-rod-wonder-effects','Rod of Wonder Effect Table','236-237','table',
 'The standard d% effects produced by a rod of wonder.',
 '["magic-items","rods","rod-of-wonder","random-effect"]',
 '{"ranges":[[1,5,"slow target 10 rounds; Will DC 15 negates"],[6,10,"faerie fire target"],[11,15,"wielder falsely believes a second rolled effect occurs for 1 round"],[16,20,"windstorm-force gust of wind; Fortitude DC 14 negates"],[21,25,"surface thoughts of target for 1d4 rounds"],[26,30,"stinking cloud at 30 feet; Fortitude DC 15 negates"],[31,33,"heavy rain for 1 round in 60-foot radius around wielder"],[34,36,"summon rhino 25%, elephant 25%, or mouse 50%"],[37,46,"70-foot lightning bolt, 6d6; Reflex DC 15 half"],[47,49,"600 butterflies for 2 rounds; blind creatures within 25 feet, Reflex DC 14 negates"],[50,53,"enlarge person within 60 feet; Fortitude DC 13 negates"],[54,58,"30-foot-diameter darkness hemisphere centered 30 feet away"],[59,62,"grass grows across 160 square feet or existing grass becomes ten times normal size"],[63,65,"nonliving object up to 1,000 pounds and 30 cubic feet turns ethereal"],[66,69,"wielder reduced to one-twelfth height"],[70,79,"fireball at target or 100 feet ahead, 6d6; Reflex DC 15 half"],[80,84,"wielder becomes invisible"],[85,87,"leaves grow from target within 60 feet for 24 hours"],[88,90,"10-40 one-gp gems stream 30 feet; roll 5d4 one-point hits and distribute among targets"],[91,95,"shimmering colors fill 40-by-30-foot area; creatures blinded 1d6 rounds, Fortitude DC 15 negates"],[96,97,"50% wielder or 50% target permanently turns blue, green, or purple"],[98,100,"flesh to stone, or stone to flesh if target is already stone, within 60 feet; Fortitude DC 18 negates"]]}')
)
INSERT INTO dnd35_rules
 (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
  category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'dmg-rule-'||d.slug,'dmg-3.5',d.page,d.slug,d.name,d.summary,d.summary,0,NULL,1,
       'magic-items',d.kind,0,1,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_rules r WHERE r.source_id='dmg-3.5' AND r.slug=d.slug AND r.owner_user_id IS NULL);
